1	import Link from "next/link";
2	import { CircleCheck, Phone, Settings, Download } from "lucide-react";
3	import { Card } from "@/components/ui/Card";
4	import { Button } from "@/components/ui/Button";
5	import { StatusBadge } from "@/components/ui/StatusBadge";
6	import { DashboardHeader } from "@/components/dashboard/DashboardHeader";
7	import { FavoriteListeners } from "@/components/customer/FavoriteListeners";
8	import { UpcomingBookings } from "@/components/customer/UpcomingBookings";
9	import { PastSessionsTable } from "@/components/customer/PastSessionsTable";
10	import { requireRole } from "@/lib/auth";
11	import {
12	  listCustomerBookings,
13	  listCustomerCompletedSessions,
14	  listCustomerPayments,
15	  listCustomerReviews,
16	  listFavoriteProviders,
17	  getApprovedProvidersByIds,
18	} from "@/lib/db/queries";
19	import { getVoiceIntroSignedUrl } from "@/lib/storage";
20	import { formatCents } from "@/lib/format";
21	import { shortDate, durationLabel } from "@/lib/time";
22	import { t } from "@/lib/i18n";
23	
24	export const metadata = { title: `${t("account.title")} · ${t("app.name")}` };
25	
26	export default async function AccountPage({
27	  searchParams,
28	}: {
29	  searchParams: Promise<{ booked?: string }>;
30	}) {
31	  const profile = await requireRole("customer");
32	  const { booked } = await searchParams;
33	
34	  const [bookings, sessions, payments, reviews, favorites] = await Promise.all([
35	    listCustomerBookings(profile.id),
36	    listCustomerCompletedSessions(profile.id),
37	    listCustomerPayments(profile.id),
38	    listCustomerReviews(profile.id),
39	    listFavoriteProviders(profile.id),
40	  ]);
41	
42	  // Resolve listener names for bookings + sessions.
43	  const providerIds = Array.from(
44	    new Set([
45	      ...bookings.map((b) => b.provider_id),
46	      ...sessions.map((s) => s.provider_id),
47	    ]),
48	  );
49	  const providersById = await getApprovedProvidersByIds(providerIds);
50	  const nameFor = (id: string) => providersById.get(id)?.display_name ?? "—";
51	
52	  const favoritesWithAudio = await Promise.all(
53	    favorites.map(async (provider) => ({
54	      provider,
55	      audioUrl: await getVoiceIntroSignedUrl(provider.voice_intro_path),
56	    })),
57	  );
58	
59	  // Sort by actual chronology: in-progress first, then "now" bookings, then
60	  // scheduled by their time — so "Next session" is the soonest, not the latest
61	  // created.
62	  const sortKey = (b: (typeof bookings)[number]) =>
63	    b.status === "in_progress"
64	      ? 0
65	      : b.scheduled_at
66	        ? new Date(b.scheduled_at).getTime()
67	        : 1; // a "now" booking is imminent
68	  const upcoming = bookings
69	    .filter((b) => b.status === "confirmed" || b.status === "in_progress")
70	    .sort((a, b) => sortKey(a) - sortKey(b))
71	    .map((b) => ({
72	      id: b.id,
73	      providerName: nameFor(b.provider_id),
74	      blockMinutes: b.block_minutes,
75	      status: b.status as "confirmed" | "in_progress",
76	      whenLabel: b.scheduled_at
77	        ? shortDate(b.scheduled_at)
78	        : t("account.talkNow"),
79	    }));
80	
81	  const next = upcoming[0];
82	
83	  const reviewedSessionIds = new Set(
84	    reviews.map((r) => r.session_id).filter(Boolean),
85	  );
86	  // Receipts only make sense for completed sessions; an authorized hold on an
87	  // upcoming booking has no receipt yet.
88	  const completedBookingIds = new Set(sessions.map((s) => s.booking_id));
89	  const PAY_STATUS: Record<
90	    string,
91	    { labelKey: "account.payAuthorized" | "account.payCaptured" | "account.payRefunded" | "account.payFailed"; tone: "success" | "neutral" | "alert" }
92	  > = {
93	    authorized: { labelKey: "account.payAuthorized", tone: "neutral" },
94	    captured: { labelKey: "account.payCaptured", tone: "success" },
95	    refunded: { labelKey: "account.payRefunded", tone: "neutral" },
96	    failed: { labelKey: "account.payFailed", tone: "alert" },
97	  };
98	  const receipts = payments
99	    .filter((p) => completedBookingIds.has(p.booking_id))
100	    .map((p) => {
101	      const booking = bookings.find((b) => b.id === p.booking_id);
102	      const name = booking ? nameFor(booking.provider_id) : "—";
103	      return {
104	        id: p.id,
105	        bookingId: p.booking_id,
106	        amountCents: p.amount_cents,
107	        status: p.status,
108	        dateLabel: shortDate(p.created_at),
109	        listenerName: name,
110	      };
111	    });
112	  const pastRows = sessions.map((s) => ({
113	    id: s.id,
114	    bookingId: s.booking_id,
115	    dateLabel: shortDate(s.ended_at),
116	    endedAtMs: s.ended_at ? new Date(s.ended_at).getTime() : 0,
117	    listenerName: nameFor(s.provider_id),
118	    durationLabel: durationLabel(s.elapsed_seconds),
119	    amountCents: s.total_price_cents,
120	    hasReview: reviewedSessionIds.has(s.id),
121	  }));
122	
123	  return (
124	    <div className="flex flex-col gap-8">
125	      <DashboardHeader
126	        title={t("account.title")}
127	        description={t("account.subtitle")}
128	        action={
129	          <Link href="/account/settings" className="rounded-btn">
130	            <Button variant="ghost" icon={Settings}>
131	              {t("account.settingsLink")}
132	            </Button>
133	          </Link>
134	        }
135	      />
136	
137	      {booked ? (
138	        <Card
139	          role="status"
140	          className="flex items-center gap-3 border-l-4 border-success bg-success-tint"
141	        >
142	          <CircleCheck size={22} aria-hidden="true" className="text-success" />
143	          <p className="text-base font-bold text-ink">
144	            {t("account.bookedConfirmed")}
145	          </p>
146	        </Card>
147	      ) : null}
148	
149	      {/* Resume / quick start */}
150	      <Card
151	        as="section"
152	        className="flex flex-col gap-4 bg-primary-tint sm:flex-row sm:items-center sm:justify-between"
153	      >
154	        <div className="flex flex-col gap-1">
155	          <h2 className="text-h3">{t("account.resumeHeading")}</h2>
156	          <p className="text-base text-ink-soft">
157	            {next
158	              ? `${t("account.nextSession")}: ${next.providerName} · ${next.whenLabel}`
159	              : t("account.nextSessionNone")}
160	          </p>
161	        </div>
162	        <div className="flex flex-wrap gap-3">
163	          {next ? (
164	            <Link href={`/session/${next.id}`} className="rounded-btn">
165	              <Button variant="ghost">{t("account.join")}</Button>
166	            </Link>
167	          ) : null}
168	          <Link href="/browse?available=1" className="rounded-btn">
169	            <Button icon={Phone}>{t("account.talkNow")}</Button>
170	          </Link>
171	        </div>
172	      </Card>
173	
174	      {/* Favorites */}
175	      <section className="flex flex-col gap-4">
176	        <h2 className="text-h2">{t("account.favoritesHeading")}</h2>
177	        <FavoriteListeners items={favoritesWithAudio} />
178	      </section>
179	
180	      {/* Upcoming bookings */}
181	      <section className="flex flex-col gap-4">
182	        <h2 className="text-h2">{t("account.upcomingHeading")}</h2>
183	        <UpcomingBookings items={upcoming} />
184	      </section>
185	
186	      {/* Past sessions */}
187	      <section className="flex flex-col gap-4">
188	        <h2 className="text-h2">{t("account.pastHeading")}</h2>
189	        <PastSessionsTable rows={pastRows} />
190	      </section>
191	
192	      {/* Receipts */}
193	      <section className="flex flex-col gap-4">
194	        <h2 className="text-h2">{t("account.receiptsHeading")}</h2>
195	        {receipts.length === 0 ? (
196	          <Card>
197	            <p className="text-base text-ink-soft">{t("account.receiptsNone")}</p>
198	          </Card>
199	        ) : (
200	          <ul className="flex flex-col gap-3">
201	            {receipts.map((r) => {
202	              const pay = PAY_STATUS[r.status] ?? {
203	                labelKey: "account.payAuthorized" as const,
204	                tone: "neutral" as const,
205	              };
206	              return (
207	                <Card
208	                  as="li"
209	                  key={r.id}
210	                  className="flex flex-wrap items-center justify-between gap-3"
211	                >
212	                  <div className="flex items-center gap-3">
213	                    <span className="text-base font-bold text-ink">
214	                      {formatCents(r.amountCents)}
215	                    </span>
216	                    <StatusBadge tone={pay.tone}>{t(pay.labelKey)}</StatusBadge>
217	                    <span className="text-sm text-ink-soft">
218	                      {r.listenerName} · {r.dateLabel}
219	                    </span>
220	                  </div>
221	                  <a
222	                    href={`/account/receipt/${r.bookingId}`}
223	                    aria-label={t("account.downloadFor", {
224	                      name: r.listenerName,
225	                      date: r.dateLabel,
226	                    })}
227	                    className="inline-flex items-center gap-1.5 text-base font-bold text-primary underline underline-offset-[3px]"
228	                  >
229	                    <Download size={16} strokeWidth={2} aria-hidden="true" />
230	                    {t("account.download")}
231	                  </a>
232	                </Card>
233	              );
234	            })}
235	          </ul>
236	        )}
237	      </section>
238	    </div>
239	  );
240	}
