1	import { notFound, redirect } from "next/navigation";
2	import { SessionFlow } from "@/components/session/SessionFlow";
3	import { requireRole } from "@/lib/auth";
4	import { getBooking, getApprovedProvider } from "@/lib/db/queries";
5	
6	export default async function SessionPage({
7	  params,
8	}: {
9	  params: Promise<{ id: string }>;
10	}) {
11	  await requireRole("customer");
12	  const { id } = await params;
13	  const booking = await getBooking(id);
14	  if (!booking) notFound();
15	  if (booking.status === "completed") redirect(`/session/${id}/summary`);
16	
17	  const provider = await getApprovedProvider(booking.provider_id);
18	  if (!provider) notFound();
19	
20	  return (
21	    <SessionFlow
22	      bookingId={id}
23	      name={provider.display_name}
24	      avatarColor={provider.avatar_color}
25	    />
26	  );
27	}
